import {SCHEMA,COLORS,makePlan,createVariant,verifySubmission,challengeImage,openBook,moveQuestion} from './workbook-engine.js';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let baseBytes,plans=[],versions=[],receipt,results=[],worker,job=0;const pending=new Map();
const say=(s,error=false)=>{$('status').textContent=s;$('status').classList.toggle('error',error);};
function download(bytes,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
const jsonDownload=(v,name)=>download(JSON.stringify(v,null,2),name,'application/json');
function csv(rows){return rows.map(r=>r.map(v=>{v=String(v??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function options(){const studentIds=$('student-ids').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean),count=Number($('count').value);if(studentIds.length&&studentIds.length!==count)throw Error('Provide one student ID for every version, or leave the field blank.');if(new Set(studentIds).size!==studentIds.length)throw Error('Assigned student IDs must be unique.');return {course:$('course').value.trim(),assignment:$('assignment').value.trim(),count,seed:$('seed').value.trim(),shuffle:$('shuffle').checked,rename:$('rename').checked,periods:$('periods').checked,scale:$('scale').checked,imageCount:Number($('image-count').value),imageStyle:$('image-style').value,accessible:$('accessible').checked,studentIds};}
function newSeed(){$('seed').value=crypto.randomUUID().slice(0,18);}
function invalidate(){plans=[];$('generate-button').disabled=true;$('preview-version').disabled=true;$('preview').innerHTML='<div class="empty">Preview again after changing the settings.</div>';}
newSeed();$('new-seed').onclick=()=>{newSeed();invalidate();};$('options').addEventListener('input',invalidate);
async function loadBase(){if(!baseBytes){const response=await fetch('../assets/SalesSimulationSpring2026.xlsm');if(!response.ok)throw Error('The supplied base workbook could not load.');baseBytes=await response.arrayBuffer();}return baseBytes;}
$('base-file').onchange=async e=>{try{const file=e.target.files[0];baseBytes=file?await file.arrayBuffer():null;if(file){const b=await openBook(baseBytes,file.name);if(!b.sheets.has('Reference')||!b.sheets.has('Title Page'))throw Error('Choose the original, ungenerated sales-case macro workbook.');}$('base-label').textContent=file?file.name:'Supplied SalesSimulationSpring2026.xlsm. The original stays unchanged.';invalidate();say('Base workbook selected.');}catch(e){baseBytes=null;say(e.message,true);}};
$('options').onsubmit=async e=>{e.preventDefault();try{const o=options();await loadBase();plans=Array.from({length:o.count},(_,i)=>makePlan(o,i));$('preview-version').innerHTML=plans.map((p,i)=>`<option value="${i}">${escape(p.id)}</option>`).join('');$('preview-version').disabled=false;$('generate-button').disabled=false;renderPreview();say('Review the questions and image, then generate the workbooks.');}catch(e){say(e.message,true);}};
function renderPreview(){const p=plans[Number($('preview-version').value)];if(!p)return;$('preview').innerHTML=`<table class="question-table"><thead><tr><th>Answer cell</th><th>Question</th><th>Order</th></tr></thead><tbody>${p.questions.map((q,i)=>`<tr><td>${escape(q.cell)}</td><td>${escape(q.label)}</td><td class="order"><button data-move="${i}" data-direction="-1" aria-label="Move question ${i+1} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-direction="1" aria-label="Move question ${i+1} down" ${i===9?'disabled':''}>↓</button></td></tr>`).join('')}</tbody></table>${p.checks.map(c=>`<div class="image-preview"><img src="${challengeImage(c)}" alt="Instructor preview: type ${c.answer} in the ${COLORS[c.target].name} box; leave the other boxes empty."><div class="boxes">${c.boxes.map(b=>`<div class="color-box" style="background:#${b.hex}"><b>${escape(b.label)}</b>${escape(b.cell)}</div>`).join('')}</div></div>`).join('')}`;$('preview').querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{moveQuestion(p,Number(b.dataset.move),Number(b.dataset.direction));renderPreview();say('Question order updated for '+p.id+'. Generate again to issue this order.');});}
$('preview-version').onchange=renderPreview;
$('generate-button').onclick=async()=>{
 if(!plans.length)return;$('generate-button').disabled=true;$('preview-button').disabled=true;
 try{const generated=[];for(let i=0;i<plans.length;i++){say(`Generating workbook ${i+1} of ${plans.length}…`);await new Promise(r=>setTimeout(r,0));generated.push(await createVariant(await loadBase(),plans[i]));}
  versions=generated;receipt={schema:SCHEMA,createdAt:new Date().toISOString(),versions:versions.map(v=>v.receipt)};$('receipt-status').textContent=`${receipt.versions.length} issued version(s) loaded from this generation.`;
  $('downloads').hidden=false;$('grade-button').disabled=false;$('version-list').innerHTML=versions.map((v,i)=>`<article class="version"><h3>${escape(v.receipt.id)}</h3><code>${v.receipt.checksum}</code><div class="actions"><button class="secondary" data-workbook="${i}">Download .xlsm</button><button class="secondary" data-copy="${i}">Copy checksum</button></div></article>`).join('');
  $('version-list').querySelectorAll('[data-workbook]').forEach(b=>b.onclick=()=>{const v=versions[Number(b.dataset.workbook)];download(v.bytes,v.filename,'application/vnd.ms-excel.sheet.macroEnabled.12');});
  $('version-list').querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(versions[Number(b.dataset.copy)].receipt.checksum);say('Checksum copied.');}catch{say('Select and copy the displayed checksum.');}});
  say('Workbooks generated. Download the instructor package and keep its receipt private.');
 }catch(e){say(e.message,true);}finally{$('generate-button').disabled=!plans.length;$('preview-button').disabled=false;}
};
$('download-receipt').onclick=()=>jsonDownload(receipt,'INSTRUCTOR_ONLY_Receipt.json');
$('download-checksums').onclick=()=>download(csv([['Version','SHA-256 checksum'],...versions.map(v=>[v.receipt.id,v.receipt.checksum])]),'Assignment_Checksums.csv','text/csv');
$('download-package').onclick=async()=>{const z=new globalThis.JSZip();for(const v of versions)z.file('workbooks/'+v.filename,v.bytes);z.file('INSTRUCTOR_ONLY/Receipt.json',JSON.stringify(receipt,null,2));z.file('INSTRUCTOR_ONLY/Checksums.csv',csv([['Version','SHA-256 checksum'],...versions.map(v=>[v.receipt.id,v.receipt.checksum])]));z.file('READ_ME.txt','Distribute only the workbooks/*.xlsm files. Keep INSTRUCTOR_ONLY private.\nStudents: use desktop Excel, click the original Generate Data button once, complete Solution and its image instruction, and save.\nInstructors: open the instructor website, load Receipt.json, and check the saved student workbooks.\nMatching checks do not establish that no assistance was used.\n');download(await z.generateAsync({type:'uint8array',compression:'DEFLATE'}),'ACC3000_Instructor_Package.zip','application/zip');};
function view(name){const grade=name==='grade';$('create-view').hidden=grade;$('grade-view').hidden=!grade;for(const id of ['create','grade']){$(id+'-tab').classList.toggle('active',(id==='grade')===grade);$(id+'-tab').setAttribute('aria-selected',String((id==='grade')===grade));}}
$('create-tab').onclick=()=>view('create');$('grade-tab').onclick=()=>view('grade');
$('receipt-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error('Receipt exceeds 1 MB.');const parsed=JSON.parse(await f.text());if(parsed.schema!==SCHEMA||!Array.isArray(parsed.versions)||!parsed.versions.length||parsed.versions.length>100)throw Error('This is not a valid instructor receipt.');if(new Set(parsed.versions.map(v=>v.id)).size!==parsed.versions.length)throw Error('Receipt contains duplicate version identifiers.');receipt=parsed;$('receipt-status').textContent=receipt.versions.length+' issued version(s) loaded.';$('grade-button').disabled=false;say('Instructor receipt loaded.');}catch(e){receipt=null;$('grade-button').disabled=true;say(e.message,true);}};
function python(input){if(!worker){worker=new Worker(new URL('./python-worker.js',import.meta.url));worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result);};worker.onerror=e=>{for(const p of pending.values())p.reject(Error(e.message||'Python could not start.'));pending.clear();worker.terminate();worker=null;};}return new Promise((resolve,reject)=>{const id=++job;pending.set(id,{resolve,reject});worker.postMessage({id,...input});});}
async function identify(bytes,name){const b=await openBook(bytes,name);for(const p of Object.keys(b.z.files).filter(p=>/^customXml\/[^/]+\.xml$/.test(p))){const d=new DOMParser().parseFromString(await b.z.file(p).async('string'),'application/xml');if(d.documentElement.namespaceURI==='urn:acc3000:assignment')return JSON.parse(d.documentElement.textContent).id;}throw Error('This is a legacy or different workbook with no issued assignment definition.');}
$('grade-button').onclick=async()=>{
 const files=[...$('submission-files').files];if(!receipt||!files.length){say('Load an instructor receipt and select one or more workbooks.',true);return;}
 const expected=$('expected-checksum').value.trim().toLowerCase();if(expected&&!/^[a-f0-9]{64}$/.test(expected)){say('Enter all 64 hexadecimal checksum characters, or leave the additional check blank.',true);return;}
 $('grade-button').disabled=true;results=[];$('grade-results').innerHTML='';
 try{for(let i=0;i<files.length;i++){
  const f=files[i];say(`Checking ${i+1} of ${files.length}: ${f.name}`);
  try{const bytes=await f.arrayBuffer(),id=await identify(bytes,f.name),issued=receipt.versions.find(v=>v.id===id);if(!issued)throw Error('This version was not issued under the loaded receipt.');if(expected&&expected!==issued.checksum)throw Error('The recorded checksum does not match this version.');
   const integrity=await verifySubmission(bytes,f.name,issued);say('Integrity matched. Loading the Python numerical grader…');const technical=await python({bytes,name:f.name,receipt:issued});if(!technical.valid)throw Error(technical.reason);
   results.push({file:f.name,version:id,integrity,technical,valid:true});
  }catch(e){results.push({file:f.name,valid:false,reason:e.message});}renderResults();
 }say('Checking complete. Results stay in this browser unless you download them.');$('export-results').disabled=!results.length;
 }finally{$('grade-button').disabled=!receipt;}
};
function renderResults(){$('grade-results').innerHTML=results.map(r=>r.valid?`<article class="panel result-card passed"><h3>${escape(r.file)}</h3><p>${escape(r.integrity.identity.first)} ${escape(r.integrity.identity.last)} · ${escape(r.integrity.identity.id)} · ${escape(r.version)}</p><div class="result-summary"><span class="pill">Checksum matched</span><span class="pill">Technical answers: ${r.technical.earned}/10</span><span class="pill">Image instructions: ${r.integrity.visual.filter(v=>v.passed).length}/${r.integrity.visual.length}</span></div><details><summary>Answer checks</summary><table class="results"><thead><tr><th>Cell</th><th>Question</th><th>Result</th></tr></thead><tbody>${r.technical.results.map(q=>`<tr><td>${escape(q.cell)}</td><td>${escape(q.title)}</td><td>${escape(q.status)}</td></tr>`).join('')}${r.integrity.visual.map(v=>`<tr><td>${escape(v.expectedCell)}</td><td>Image instruction</td><td>${v.passed?'correct':escape(v.message)}</td></tr>`).join('')}</tbody></table></details></article>`:`<article class="panel result-card rejected"><h3>${escape(r.file)}</h3><p class="error-text">Version rejected — not graded</p><p>${escape(r.reason)}</p></article>`).join('');}
$('export-results').onclick=()=>download(csv([['File','Version','Student ID','First name','Last name','Integrity','Technical score / 10','Image checks passed','Image checks total','Reason'],...results.map(r=>r.valid?[r.file,r.version,r.integrity.identity.id,r.integrity.identity.first,r.integrity.identity.last,'matched',r.technical.earned,r.integrity.visual.filter(v=>v.passed).length,r.integrity.visual.length,'']:[r.file,'','','','','rejected','','','',r.reason])]),'ACC3000_Grading_Results.csv','text/csv');
